SELECT DISTINCT Match_Id
FROM Wicket_Taken
WHERE Kind_Out IN (SELECT Out_Id FROM Out_Type WHERE LOWER(Out_Name) LIKE '%hit wicket%');

SELECT Umpire_Name
FROM Umpire
WHERE Umpire_Country IN (SELECT Country_Id FROM Country WHERE LOWER(Country_Name) = LOWER('new zealand'));

SELECT CAST(SUM(CASE WHEN LOWER(V.Venue_Name) LIKE '%dr dy patil sports academy%' AND M.Win_Margin < 10 THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) AS percentage
FROM Match M
JOIN Venue V ON M.Venue_Id = V.Venue_Id;

SELECT COUNT(DISTINCT Match_Id) AS match_count
FROM Batsman_Scored
WHERE Innings_No = 2;

SELECT Name, (ListPrice - StandardCost) AS Profit
FROM Product
WHERE (ListPrice - StandardCost) > 100;

SELECT MAX(review_count) AS max_reviews
FROM (
    SELECT COUNT(ProductID) AS review_count
    FROM Product
    WHERE FinishedGoodsFlag = 1
);

SELECT MIN(SafetyStockLevel) AS MinInventoryQuantity
FROM Product
WHERE LOWER(Name) LIKE '%chainring%';

SELECT TOP 1 Name, (ListPrice - StandardCost) AS Profit
FROM Product
ORDER BY (ListPrice - StandardCost) DESC;

SELECT ProductID, Name, StandardCost
FROM Product
WHERE StandardCost < (SELECT AVG(StandardCost) FROM Product);

SELECT e.GDP * e.Service AS ServiceOfGDP
FROM economy e
WHERE LOWER(e.Country) = 'brazil';

SELECT MAX(Length) AS LongestRiverLength
FROM river
WHERE River IN (SELECT Name FROM sea WHERE Name = 'Mediterranean Sea');

SELECT Country1 AS Country1_Name, Country2 AS Country2_Name
FROM borders
WHERE Length = 803;

SELECT SUM(Population) AS total_population
FROM province
WHERE LOWER(Name) = 'fareham';
